// Mycelium public swarms (demo). No accounts: one Ed25519 key per browser,
// generated by WebCrypto as NON-EXTRACTABLE and kept in IndexedDB. Every write is a
// signed document (same canonical bytes as mycelium_swarm_directory/wire.py).
// Prompts go straight to the swarm's entry Mac, which enforces the owner-signed
// grant; this directory never sees them. No analytics, no cookies.
'use strict';
const $ = (id) => document.getElementById(id);
const API = '/swarms/api/v1';
const SIG_PREFIX = 'mycelium-swarm-sig-v1\n';
const enc = new TextEncoder();
let me = null;          // {privateKey, publicKey, key: 'ed25519:..', fp}
let config = null;
let swarms = [];
let mine = {grants: [], denied: [], pending: []};
let chatTarget = null;  // {swarm, grant}
let sending = false;

// -- canonical JSON + encodings (must match wire.py) ------------------------------
function canonical(v) {
  if (v === null) return 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'number') { if (!Number.isSafeInteger(v)) throw new Error('float_refused'); return String(v); }
  if (typeof v === 'string') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(canonical).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + canonical(v[k])).join(',') + '}';
}
function b64url(bytes) {
  let s = ''; for (const b of new Uint8Array(bytes)) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function unb64url(text) {
  const raw = atob(text.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((text.length + 3) % 4));
  return Uint8Array.from(raw, (c) => c.charCodeAt(0));
}
function randomText(bytes) { return b64url(crypto.getRandomValues(new Uint8Array(bytes))); }
function now() { return Math.floor(Date.now() / 1000); }
async function fingerprint(key) {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', unb64url(key.slice(8))));
  const hex = Array.from(digest.slice(0, 8), (b) => b.toString(16).padStart(2, '0')).join('').toUpperCase();
  return hex.match(/.{4}/g).join('-');
}

// -- key storage (IndexedDB; the private key cannot be exported) ------------------
function db() {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open('mycelium-swarms', 1);
    open.onupgradeneeded = () => { open.result.createObjectStore('kv'); };
    open.onsuccess = () => resolve(open.result); open.onerror = () => reject(open.error);
  });
}
async function kv(mode, fn) {
  const handle = await db();
  return new Promise((resolve, reject) => {
    const tx = handle.transaction('kv', mode); const req = fn(tx.objectStore('kv'));
    tx.oncomplete = () => resolve(req && req.result); tx.onerror = () => reject(tx.error);
  });
}
async function loadIdentity() {
  let stored = await kv('readonly', (s) => s.get('identity'));
  if (!stored) {
    const pair = await crypto.subtle.generateKey({name: 'Ed25519'}, false, ['sign', 'verify']);
    const raw = await crypto.subtle.exportKey('raw', pair.publicKey);  // public half only
    stored = {privateKey: pair.privateKey, publicKey: pair.publicKey, key: 'ed25519:' + b64url(raw)};
    await kv('readwrite', (s) => s.put(stored, 'identity'));
  }
  me = {...stored, fp: await fingerprint(stored.key)};
}
async function sign(doc) {
  const body = {...doc}; delete body.sig;
  const signature = await crypto.subtle.sign({name: 'Ed25519'}, me.privateKey, enc.encode(SIG_PREFIX + canonical(body)));
  return {...body, sig: b64url(signature)};
}
async function openGrants() { return (await kv('readonly', (s) => s.get('open-grants'))) || {}; }
async function saveOpenGrant(grant) {
  const all = await openGrants(); all[grant.swarm_id] = grant;
  await kv('readwrite', (s) => s.put(all, 'open-grants'));
}

// -- network --------------------------------------------------------------------------
async function directory(path, doc) {
  const init = doc === undefined ? {cache: 'no-store'} : {method: 'POST', cache: 'no-store',
    headers: {'Content-Type': 'application/json', 'X-Mycelium-Swarms': '1'}, body: JSON.stringify(doc)};
  const response = await fetch(API + path, {...init, credentials: 'omit', redirect: 'error', referrerPolicy: 'no-referrer'});
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'request_failed');
  return value;
}
async function entry(origin, route, doc) {
  const response = await fetch(origin + '/swarm-entry/v1/' + route, {method: 'POST', mode: 'cors', cache: 'no-store',
    credentials: 'omit', redirect: 'error', referrerPolicy: 'no-referrer',
    headers: {'Content-Type': 'application/json'}, body: JSON.stringify(doc)});
  const value = await response.json();
  if (!response.ok) throw new Error(value.error || 'request_failed');
  return value;
}

const MESSAGES = {
  chat_not_ready: 'The swarm is not serving right now.',
  chat_warming_up: 'Warming up: the swarm is qualifying its route.',
  chat_route_not_qualified: 'The route is not qualified yet. Try again in a moment.',
  chat_busy: 'Another prompt is running on this swarm. Try again in a few seconds.',
  chat_rate_limited: 'You sent several prompts this minute. Wait a little.',
  chat_swarm_rate_limited: 'This swarm got many prompts this minute. Wait a little.',
  entry_rate_limited_key: 'You sent several prompts this minute. Wait a little.',
  entry_rate_limited_ip: 'Many prompts from your network this minute. Wait a little.',
  entry_quota_exhausted: 'Your grant for this swarm is used up. Ask the owner for a new one.',
  entry_grant_expired: 'Your grant expired. Ask the owner for a new one.',
  entry_grant_revoked: 'The owner revoked your grant.',
  entry_grant_issuer_invalid: 'The swarm did not accept this grant (not signed by its owner).',
  entry_grant_signature_invalid: 'The grant signature is invalid.',
  entry_not_published: 'This Mac is not serving this swarm right now.',
  entry_clock_skew: 'Your computer clock is off by more than two minutes.',
  entry_prompt_too_long: 'That prompt is too long (2,000 characters at most).',
  swarm_invite_only: 'This swarm is invite only.',
  rate_limited_ip: 'Too many requests from your network. Wait a minute.',
  rate_limited_key: 'Too many requests from your key. Wait a minute.',
};
const say = (code) => MESSAGES[code] || code;

// -- rendering ----------------------------------------------------------------------
function el(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs || {})) {
    if (k === 'class') node.className = v; else if (k === 'on') node.addEventListener('click', v);
    else if (k === 'hidden') node.hidden = v; else node.setAttribute(k, v);
  }
  for (const child of children) if (child !== null && child !== undefined) node.append(child);
  return node;
}
function grantFor(swarmId) { return mine.grants.find((g) => g.swarm_id === swarmId) || mine.open[swarmId] || null; }

function renderSwarm(s) {
  const grant = grantFor(s.swarm_id);
  const actions = el('div', {class: 'actions'});
  const note = el('p', {class: 'meta'});
  const usable = s.entry_origin && s.status === 'serving';
  if (grant && grant.expires_at > now()) {
    actions.append(el('button', {type: 'button', on: () => openChat(s, grant), ...(usable ? {} : {disabled: ''})}, 'Chat'));
    note.textContent = `You have access until ${new Date(grant.expires_at * 1000).toLocaleString()} ` +
      `(${grant.max_requests} requests, ${grant.max_tokens} tokens).`;
  } else if (s.owner_key === me.key) {
    note.textContent = 'You own this swarm. Grant yourself access below to chat with it.';
  } else if (s.access_mode === 'open') {
    actions.append(el('button', {type: 'button', on: () => getOpenAccess(s), ...(s.entry_origin ? {} : {disabled: ''})}, 'Get open access'));
    if (s.open_quota) note.textContent = `Automatic access: ${s.open_quota.max_requests} requests, ${s.open_quota.max_tokens} tokens per key.`;
  } else if (s.access_mode === 'request') {
    if (mine.denied.includes(s.swarm_id)) note.textContent = 'The owner declined your request.';
    else if (mine.pending.includes(s.swarm_id)) note.textContent = 'Request sent. Waiting for the owner.';
    const input = el('input', {maxlength: '140', placeholder: 'Optional note to the owner (140 characters)', 'aria-label': 'Note to the owner'});
    actions.append(input, el('button', {type: 'button', on: () => requestAccess(s, input.value.trim())}, 'Request access'));
  } else {
    note.textContent = `Invite only. Ask the owner (key ${s.owner_fingerprint}) to grant your key ${me.fp}.`;
  }
  return el('div', {class: 'swarm', 'data-swarm': s.swarm_id},
    el('h3', {}, s.name, el('span', {class: 'status ' + s.status}, s.status)),
    el('p', {class: 'meta'}, `Model ${s.served_model || s.model} · ${s.members} Mac${s.members === 1 ? '' : 's'} · access ${s.access_mode} · owner ${s.owner_fingerprint}` +
      (s.entry_fingerprint ? ` · entry ${s.entry_fingerprint}` : ' · no entry Mac yet')),
    s.description ? el('p', {}, s.description) : null,
    el('p', {class: 'privacy'}, s.privacy), note, actions);
}

async function refresh() {
  try {
    const listing = await directory('/swarms');
    swarms = listing.swarms;
    try { mine = await directory('/my-grants', await sign({protocol: 'mycelium.swarm.grantee_query.v1', grantee_key: me.key, at: now(), nonce: randomText(18)})); }
    catch (error) { mine = {grants: [], denied: [], pending: []}; }
    mine.open = {};
    for (const [id, g] of Object.entries(await openGrants())) if (g.expires_at > now()) mine.open[id] = g;
    $('swarms').replaceChildren(...swarms.map(renderSwarm));
    $('list-state').textContent = swarms.length ? `${swarms.length} swarm${swarms.length === 1 ? '' : 's'} (all visible for this demo).` : 'No swarms yet. Create one below.';
    renderOwned();
  } catch (error) { $('list-state').textContent = 'Cannot reach the directory right now (the demo host may be asleep).'; }
}

// -- visitor actions -------------------------------------------------------------------
async function requestAccess(s, note) {
  try {
    await directory('/access-requests', await sign({protocol: 'mycelium.swarm.access_request.v1', swarm_id: s.swarm_id,
      requester_key: me.key, note, at: now()}));
    $('list-state').textContent = `Request sent to ${s.name}. The owner sees your key ${me.fp}.`;
  } catch (error) { $('list-state').textContent = 'Not sent: ' + say(error.message); }
  refresh();
}
async function getOpenAccess(s) {
  try {
    const value = await entry(s.entry_origin, 'open-grant', await sign({protocol: 'mycelium.swarm.open_grant_request.v1',
      swarm_id: s.swarm_id, key: me.key, at: now(), nonce: randomText(18)}));
    await saveOpenGrant(value.grant);
  } catch (error) { $('list-state').textContent = 'No access: ' + say(error.message); }
  refresh();
}

// -- chat (same polling contract and failure codes as the A13 chat page) ------------
function line(kind, text) { const div = el('div', {class: 'msg ' + kind}, text); $('log').append(div); div.scrollIntoView({block: 'end'}); return div; }
async function openChat(s, grant) {
  chatTarget = {swarm: s, grant};
  $('chat-card').hidden = false; $('log').replaceChildren();
  $('chat-title').textContent = 'Chat with ' + s.name;
  $('chat-privacy').textContent = s.privacy;
  try {
    const state = await entry(s.entry_origin, 'state', {});
    $('chat-state').textContent = state.available ? `Serving ${state.model_id || ''}${state.busy ? ' · busy' : ' · ready'}` : say(state.warming_up ? 'chat_warming_up' : 'chat_not_ready');
  } catch (error) { $('chat-state').textContent = say(error.message); }
  $('chat-card').scrollIntoView();
}
async function send(event) {
  event.preventDefault();
  const prompt = $('prompt').value.trim(); if (!prompt || sending || !chatTarget) return;
  sending = true; $('send').disabled = true;
  line('you', prompt); const answer = line('swarm', '…'); const meta = line('meta', '');
  const {swarm, grant} = chatTarget;
  try {
    const accepted = await entry(swarm.entry_origin, 'send', await sign({protocol: 'mycelium.swarm.entry_send.v1',
      swarm_id: swarm.swarm_id, key: me.key, grant, prompt, max_new_tokens: Number($('tokens').value) || 128,
      at: now(), nonce: randomText(18)}));
    meta.textContent = (accepted.clamped ? `capped at ${accepted.max_new_tokens} tokens · ` : '') +
      `left on your grant: ${accepted.quota.requests_left} requests, ${accepted.quota.tokens_left} tokens`;
    $('prompt').value = '';
    let next = 0; let text = '';
    for (;;) {
      const page = await entry(swarm.entry_origin, 'events', {request_id: accepted.request_id, after: next});
      next = page.next; text += page.tokens.join(''); answer.textContent = text || '…';
      if (page.done) {
        if (page.error) answer.textContent = (text ? text + '\n' : '') + `[stopped: ${say(page.error)}]`;
        if (page.seconds !== null) meta.textContent += ` · ${page.seconds} s`;
        break;
      }
      await new Promise((resolve) => setTimeout(resolve, 600));
    }
  } catch (error) { answer.textContent = 'Not sent: ' + say(error.message); }
  finally { sending = false; $('send').disabled = false; }
}

// -- owner actions -------------------------------------------------------------------------
function newSwarmId() {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz0123456789';
  return 'sw-' + Array.from(crypto.getRandomValues(new Uint8Array(20)), (b) => alphabet[b % 36]).join('');
}
function swarmLink(swarmId) {
  return 'mycelium-swarm:' + b64url(enc.encode(canonical({protocol: 'mycelium.swarm.link.v1', directory: config.directory,
    swarm_id: swarmId, owner_key: me.key})));
}
async function create(event) {
  event.preventDefault();
  const mode = $('c-mode').value;
  const record = {protocol: 'mycelium.swarm.record.v1', swarm_id: newSwarmId(), owner_key: me.key, seq: 1,
    name: $('c-name').value.trim(), model: $('c-model').value.trim(), description: $('c-desc').value.trim(),
    access_mode: mode, entry: null,
    open_quota: mode === 'open' ? {max_requests: Number($('c-req').value), max_tokens: Number($('c-tok').value), ttl_seconds: 86400} : null};
  try {
    await directory('/records', await sign(record));
    $('create-state').textContent = 'Created. Now attach a Mac: see "Swarms you own".';
    $('create-form').reset(); $('c-model').value = 'Qwen/Qwen3-0.6B';
  } catch (error) { $('create-state').textContent = 'Not created: ' + say(error.message); }
  refresh();
}
async function resign(s, changes) {
  const r = s.record;
  const record = {protocol: r.protocol, swarm_id: r.swarm_id, owner_key: r.owner_key, seq: r.seq + 1, name: r.name, model: r.model,
    description: r.description, access_mode: r.access_mode, open_quota: r.open_quota, entry: r.entry, ...changes};
  await directory('/records', await sign(record));
}
async function inbox(s) {
  return directory('/owner-inbox', await sign({protocol: 'mycelium.swarm.owner_query.v1', swarm_id: s.swarm_id, owner_key: me.key, at: now(), nonce: randomText(18)}));
}
async function approve(s, requesterKey, hours, requests, tokens) {
  const t = now();
  await directory('/grants', await sign({protocol: 'mycelium.swarm.grant.v1', grant_id: 'gr-' + randomText(16).slice(0, 22),
    swarm_id: s.swarm_id, grantee_key: requesterKey, issuer_key: me.key, issued_at: t, expires_at: t + hours * 3600,
    max_requests: requests, max_tokens: tokens}));
}
async function deny(s, requesterKey) {
  await directory('/deny', await sign({protocol: 'mycelium.swarm.deny.v1', swarm_id: s.swarm_id, owner_key: me.key, requester_key: requesterKey, at: now()}));
}
async function remove(s) {
  if (!confirm(`Delete "${s.name}" from the directory? Grants already issued stay valid at the entry until they expire.`)) return;
  await directory('/delete', await sign({protocol: 'mycelium.swarm.delete.v1', swarm_id: s.swarm_id, owner_key: me.key, seq: s.record.seq + 1}));
  refresh();
}

async function renderOwned() {
  const owned = swarms.filter((s) => s.owner_key === me.key);
  $('owned-card').hidden = !owned.length;
  const blocks = [];
  for (const s of owned) {
    const link = swarmLink(s.swarm_id);
    const box = el('div', {class: 'swarm', 'data-owned': s.swarm_id}, el('h3', {}, s.name, el('span', {class: 'status ' + s.status}, s.status)),
      el('p', {}, 'Attach a Mac: in the Mycelium app on the Mac that runs the swarm, choose "Publish this run as a swarm" and paste this link (or scan the QR). Then attach it here when its fingerprint appears.'),
      el('img', {class: 'qr', src: `${API}/swarms/${s.swarm_id}/link.svg`, alt: 'QR code of the swarm link'}),
      el('p', {class: 'mono link', 'data-link': ''}, link));
    const self = el('button', {type: 'button', on: async () => { await approve(s, me.key, 24, 50, 10000); refresh(); }}, 'Grant myself access (24 h)');
    box.append(self, el('button', {type: 'button', class: 'secondary', on: () => remove(s)}, 'Delete swarm'));
    const list = el('div', {}, el('p', {class: 'meta'}, 'Loading requests…'));
    box.append(list); blocks.push(box);
    inbox(s).then((value) => {
      const rows = [];
      if (s.entry_fingerprint) rows.push(el('p', {class: 'meta', 'data-attached': s.entry_fingerprint},
        `Attached Mac: fingerprint ${s.entry_fingerprint} at ${s.entry_origin}.`));
      for (const offer of value.entry_offers) {
        const attached = s.record.entry && s.record.entry.key === offer.entry_key;
        rows.push(el('div', {class: 'offer'}, el('p', {}, `Mac offering to serve: fingerprint ${offer.entry_fingerprint} at ${offer.origin}. Check the app shows the same fingerprint.`),
          attached ? el('p', {class: 'meta'}, 'Attached.') : el('button', {type: 'button', 'data-attach': offer.entry_fingerprint, on: async () => {
            await resign(s, {entry: {key: offer.entry_key, origin: offer.origin}}); refresh(); }}, 'Attach this Mac')));
      }
      for (const r of value.requests) {
        const hours = el('input', {type: 'number', min: '1', max: '720', value: '24', 'aria-label': 'Hours'});
        const reqs = el('input', {type: 'number', min: '1', max: '10000', value: '20', 'aria-label': 'Requests'});
        const toks = el('input', {type: 'number', min: '1', max: '1000000', value: '4000', 'aria-label': 'Tokens'});
        rows.push(el('div', {class: 'request'}, el('p', {}, `Key ${r.requester_fingerprint} · ${r.state}${r.note ? ' · “' + r.note + '”' : ''}`),
          r.state === 'pending' ? el('div', {class: 'row'}, el('label', {}, 'Hours', hours), el('label', {}, 'Requests', reqs), el('label', {}, 'Tokens', toks),
            el('button', {type: 'button', 'data-approve': r.requester_fingerprint, on: async () => { await approve(s, r.requester_key, Number(hours.value), Number(reqs.value), Number(toks.value)); refresh(); }}, 'Approve'),
            el('button', {type: 'button', class: 'secondary', on: async () => { await deny(s, r.requester_key); refresh(); }}, 'Decline')) : null));
      }
      list.replaceChildren(...(rows.length ? rows : [el('p', {class: 'meta'}, 'No access requests or Mac offers yet.')]));
    }).catch((error) => { list.replaceChildren(el('p', {class: 'error'}, 'Inbox unavailable: ' + say(error.message))); });
  }
  $('owned').replaceChildren(...blocks);
}

async function forget() {
  if (!confirm('Forget this browser key? Swarms it owns can no longer be managed and its grants stop working here.')) return;
  await kv('readwrite', (s) => s.clear());
  location.reload();
}

async function main() {
  if (!window.crypto || !crypto.subtle || !window.indexedDB) { $('identity').textContent = 'This browser lacks WebCrypto/IndexedDB.'; return; }
  try { await loadIdentity(); } catch (error) {
    $('identity').textContent = 'This browser cannot create an Ed25519 key (needs a current Chrome, Safari or Firefox).'; return;
  }
  $('identity').textContent = 'Fingerprint ' + me.fp;
  try { config = await directory('/config'); $('demo').textContent = config.demo; $('privacy').textContent = config.privacy; } catch (error) { config = {directory: location.origin}; }
  $('refresh').addEventListener('click', refresh);
  $('forget').addEventListener('click', forget);
  $('create-form').addEventListener('submit', create);
  $('chat-form').addEventListener('submit', send);
  $('chat-close').addEventListener('click', () => { $('chat-card').hidden = true; chatTarget = null; });
  document.body.dataset.ready = '1';
  await refresh();
  setInterval(refresh, 15000);
}
main();
